use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::Arc;
use std::thread;

mod crypto {
    use std::sync::atomic::{AtomicU64, Ordering};

    pub struct ChaCha20State {
        key: [u8; 32],
        counter: AtomicU64,
    }

    impl ChaCha20State {
        pub fn new(key: [u8; 32]) -> Self {
            ChaCha20State {
                key,
                counter: AtomicU64::new(0),
            }
        }

        fn quarter_round(state: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize) {
            state[a] = state[a].wrapping_add(state[b]);
            state[d] ^= state[a];
            state[d] = state[d].rotate_left(16);
            state[c] = state[c].wrapping_add(state[d]);
            state[b] ^= state[c];
            state[b] = state[b].rotate_left(12);
            state[a] = state[a].wrapping_add(state[b]);
            state[d] ^= state[a];
            state[d] = state[d].rotate_left(8);
            state[c] = state[c].wrapping_add(state[d]);
            state[b] ^= state[c];
            state[b] = state[b].rotate_left(7);
        }

        fn generate_block(&self, nonce: &[u8; 12], block_counter: u32) -> [u8; 64] {
            let mut state = [0u32; 16];
            state[0] = 0x61707865;
            state[1] = 0x3320646e;
            state[2] = 0x79622d32;
            state[3] = 0x6b206574;
            for i in 0..8 {
                state[4 + i] = u32::from_le_bytes([
                    self.key[4 * i],
                    self.key[4 * i + 1],
                    self.key[4 * i + 2],
                    self.key[4 * i + 3],
                ]);
            }
            state[12] = block_counter;
            state[13] = u32::from_le_bytes([nonce[0], nonce[1], nonce[2], nonce[3]]);
            state[14] = u32::from_le_bytes([nonce[4], nonce[5], nonce[6], nonce[7]]);
            state[15] = u32::from_le_bytes([nonce[8], nonce[9], nonce[10], nonce[11]]);

            let initial_state = state;
            for _ in 0..10 {
                Self::quarter_round(&mut state, 0, 4, 8, 12);
                Self::quarter_round(&mut state, 1, 5, 9, 13);
                Self::quarter_round(&mut state, 2, 6, 10, 14);
                Self::quarter_round(&mut state, 3, 7, 11, 15);
                Self::quarter_round(&mut state, 0, 5, 10, 15);
                Self::quarter_round(&mut state, 1, 6, 11, 12);
                Self::quarter_round(&mut state, 2, 7, 8, 13);
                Self::quarter_round(&mut state, 3, 4, 9, 14);
            }
            for i in 0..16 {
                state[i] = state[i].wrapping_add(initial_state[i]);
            }

            let mut output = [0u8; 64];
            for i in 0..16 {
                let bytes = state[i].to_le_bytes();
                output[4 * i..4 * i + 4].copy_from_slice(&bytes);
            }
            output
        }

        /// Encrypt data for a given session. The nonce is derived from
        /// the session_id to ensure uniqueness per session.
        pub fn encrypt_for_session(&self, session_id: u64, data: &[u8]) -> Vec<u8> {
            // Derive nonce: use session_id in lower 8 bytes, counter in upper 4
            let seq = self.counter.fetch_add(1, Ordering::Relaxed);
            let mut nonce = [0u8; 12];
            // Place session_id in nonce bytes 0..8
            nonce[0..8].copy_from_slice(&session_id.to_le_bytes());
            // Place sequence in nonce bytes 8..12 (truncated to u32)
            nonce[8..12].copy_from_slice(&(seq as u32).to_le_bytes());

            let mut output = Vec::with_capacity(data.len() + 12);
            output.extend_from_slice(&nonce);

            let mut pos = 0;
            let mut block_counter = 0u32;
            while pos < data.len() {
                let keystream = self.generate_block(&nonce, block_counter);
                let chunk_end = std::cmp::min(pos + 64, data.len());
                for i in pos..chunk_end {
                    output.push(data[i] ^ keystream[i - pos]);
                }
                pos = chunk_end;
                block_counter += 1;
            }
            output
        }
    }
}

struct ProxyServer {
    cipher: Arc<crypto::ChaCha20State>,
    upstream_addr: String,
}

impl ProxyServer {
    fn new(key: [u8; 32], upstream: &str) -> Self {
        ProxyServer {
            cipher: Arc::new(crypto::ChaCha20State::new(key)),
            upstream_addr: upstream.to_string(),
        }
    }

    fn handle_upload(&self, mut client: TcpStream) {
        let mut header = [0u8; 8];
        if client.read_exact(&mut header).is_err() {
            return;
        }
        let session_id = u64::from_le_bytes(header);
        let mut size_buf = [0u8; 4];
        if client.read_exact(&mut size_buf).is_err() {
            return;
        }
        let size = u32::from_le_bytes(size_buf) as usize;
        if size > 10 * 1024 * 1024 {
            let _ = client.write_all(b"ERR: too large");
            return;
        }

        let mut payload = vec![0u8; size];
        if client.read_exact(&mut payload).is_err() {
            return;
        }

        // Encrypt the upload before forwarding to upstream
        let encrypted = self.cipher.encrypt_for_session(session_id, &payload);

        // Forward to upstream
        if let Ok(mut upstream) = TcpStream::connect(&self.upstream_addr) {
            let total_len = (encrypted.len() as u32).to_le_bytes();
            let _ = upstream.write_all(&total_len);
            let _ = upstream.write_all(&encrypted);
            let _ = client.write_all(b"OK");
        } else {
            let _ = client.write_all(b"ERR: upstream");
        }
    }

    fn run(&self, bind_addr: &str) {
        let listener = TcpListener::bind(bind_addr).expect("Failed to bind");
        println!("Proxy listening on {}", bind_addr);

        for stream in listener.incoming() {
            match stream {
                Ok(client) => {
                    let cipher = Arc::clone(&self.cipher);
                    let upstream = self.upstream_addr.clone();
                    thread::spawn(move || {
                        let server = ProxyServer {
                            cipher,
                            upstream_addr: upstream,
                        };
                        server.handle_upload(client);
                    });
                }
                Err(e) => eprintln!("Accept error: {}", e),
            }
        }
    }
}

fn main() {
    // In production, key would come from secure key management
    let key = [0x42u8; 32]; // placeholder
    let server = ProxyServer::new(key, "127.0.0.1:9000");
    server.run("0.0.0.0:8080");
}
